; Philips RC5 infrared frame with a 36 kHz carrier; one 14-bit code per host word, acknowledged
; Generated by escgen from protocols/rc5_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: SB-Projects, Philips RC-5 Protocol, www.sbprojects.net/knowledge/ir/rc5.php: 36 kHz carrier, bit time 1.778 ms (64 carrier periods), Manchester, 1 = low then high, 14 bits MSB first, frames every 113.778 ms
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ PERIOD, (CLK_KHZ * 10 + 180) // 360
.equ HALF, 32 * PERIOD
.equ GAP, CLK_KHZ * 89
.equ C_PERIOD, PERIOD
.equ C_HIGH, (PERIOD + 1) // 3
.default PIN_IR, 0
.equ P_IR, 1 << PIN_IR

.own  PIN_IR, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_IR, 0, P_IR               ; idle levels
    ADDT  1
packet:
    POP   r1                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    MOV   r0, r1                      ; 14 bits, MSB first, each zero or one
    SHL   r0, 18                      ; the field's first bit to bit 31
    MOVI  r3, 0
bit1:
    SHL   r0, 1                       ; C = the next bit
    JC    one2
    LDLC  (HALF) // C_PERIOD          ; zero: carrier pulses
    CALL  burst
    ADDT  HALF - 64                   ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    JMP   next3
one2:
    EMIT  P_IR, 0, P_IR               ; one
    ADDT  HALF
    LDLC  (HALF) // C_PERIOD          ; carrier pulses
    CALL  burst
next3:
    ADDI  r3, 1
    CMPI  r3, 14                      ; Z after the last bit
    JNZ   bit1
    ADDT  GAP - 64                    ; gap: no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet

; ---- burst: lc carrier pulses from tmr; returns with tmr = start + lc * C_PERIOD
burst:
    EMIT  P_IR, P_IR, P_IR
    ADDT  C_HIGH
    EMIT  P_IR, 0, P_IR
    ADDT  C_PERIOD - C_HIGH
    DJNZ  burst
    RET
